#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <array>
#include <climits>
using namespace std;

constexpr int MAX_SIZE = 300;
constexpr int INFINITY = 1000000000;

struct Connection {
    int destination;
    int reverse_index;
    int current_flow;
    int max_capacity;
    Connection(int d, int r, int f, int c) : destination(d), reverse_index(r), current_flow(f), max_capacity(c) {}
};

vector<Connection> network[MAX_SIZE];
int level[MAX_SIZE], next_edge[MAX_SIZE], source_node, sink_node;

void connect_nodes(int from, int to, int capacity, int reverse_capacity = 0) {
    network[from].emplace_back(to, (int)network[to].size(), 0, capacity);
    network[to].emplace_back(from, (int)network[from].size() - 1, 0, reverse_capacity);
}

bool compute_levels() {
    fill(level, level + MAX_SIZE, -1);
    level[source_node] = 0;
    queue<int> q;
    q.push(source_node);
    while (!q.empty() && level[sink_node] == -1) {
        int u = q.front(); q.pop();
        for (const auto& conn : network[u]) {
            int v = conn.destination;
            if (level[v] == -1 && conn.current_flow < conn.max_capacity) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[sink_node] != -1;
}

int push_flow(int node, int bottleneck) {
    if (node == sink_node || !bottleneck) return bottleneck;
    for (int& i = next_edge[node]; i < (int)network[node].size(); ++i) {
        auto& conn = network[node][i];
        int next_node = conn.destination;
        if (level[next_node] != level[node] + 1) continue;
        int augment = push_flow(next_node, min(bottleneck, conn.max_capacity - conn.current_flow));
        if (augment) {
            conn.current_flow += augment;
            network[next_node][conn.reverse_index].current_flow -= augment;
            return augment;
        }
    }
    return 0;
}

int calculate_max_flow() {
    int total = 0;
    while (compute_levels()) {
        fill(next_edge, next_edge + MAX_SIZE, 0);
        int augment;
        while ((augment = push_flow(source_node, INFINITY))) {
            total += augment;
        }
    }
    return total;
}

const int row_offsets[4] = {-1, 0, 0, 1};
const int col_offsets[4] = {0, -1, 1, 0};

int grid_dimension, max_time;
vector<vector<int>> obstacles, time_constraints, shortest_paths;
vector<string> initial_grid, target_grid;

void multi_source_bfs(int start_row, int start_col, vector<vector<int>>& distance_map, bool apply_time_limit = false) {
    for (int i = 0; i < grid_dimension; ++i)
        fill(distance_map[i].begin(), distance_map[i].end(), -1);
    distance_map[start_row][start_col] = 0;
    queue<array<int, 2>> bfs_queue;
    bfs_queue.push({start_row, start_col});
    while (!bfs_queue.empty()) {
        auto [r, c] = bfs_queue.front(); bfs_queue.pop();
        if (apply_time_limit && distance_map[r][c] == time_constraints[r][c]) continue;
        for (int dir = 0; dir < 4; ++dir) {
            int new_r = r + row_offsets[dir];
            int new_c = c + col_offsets[dir];
            if (new_r < 0 || new_r >= grid_dimension || new_c < 0 || new_c >= grid_dimension ||
                distance_map[new_r][new_c] != -1 || obstacles[new_r][new_c]) continue;
            if (apply_time_limit && time_constraints[new_r][new_c] > -1 &&
                distance_map[r][c] + 1 > time_constraints[new_r][new_c]) continue;
            distance_map[new_r][new_c] = distance_map[r][c] + 1;
            bfs_queue.push({new_r, new_c});
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> grid_dimension >> max_time;
    initial_grid.resize(grid_dimension);
    target_grid.resize(grid_dimension);
    for (auto& s : initial_grid) cin >> s;
    for (auto& s : target_grid) cin >> s;
    obstacles.assign(grid_dimension, vector<int>(grid_dimension));
    time_constraints.assign(grid_dimension, vector<int>(grid_dimension));
    shortest_paths.assign(grid_dimension, vector<int>(grid_dimension));
    for (int i = 0; i < grid_dimension; ++i)
        for (int j = 0; j < grid_dimension; ++j)
            obstacles[i][j] = (initial_grid[i][j] == 'Y');
    for (int i = 0; i < grid_dimension; ++i)
        for (int j = 0; j < grid_dimension; ++j)
            if (initial_grid[i][j] == 'Z')
                multi_source_bfs(i, j, time_constraints);
    source_node = 2 * grid_dimension * grid_dimension + 5;
    sink_node = source_node + 1;
    for (int x = 0; x < grid_dimension; ++x) {
        for (int y = 0; y < grid_dimension; ++y) {
            if (initial_grid[x][y] == 'Z' || initial_grid[x][y] == 'Y') continue;
            connect_nodes(source_node, grid_dimension * x + y, initial_grid[x][y] - '0');
            connect_nodes(grid_dimension * grid_dimension + grid_dimension * x + y, sink_node, target_grid[x][y] - '0');
            multi_source_bfs(x, y, shortest_paths, true);
            for (int xp = 0; xp < grid_dimension; ++xp) {
                for (int yp = 0; yp < grid_dimension; ++yp) {
                    if (shortest_paths[xp][yp] != -1 && shortest_paths[xp][yp] <= max_time) {
                        connect_nodes(grid_dimension * x + y, grid_dimension * grid_dimension + grid_dimension * xp + yp, INFINITY);
                    }
                }
            }
        }
    }
    cout << calculate_max_flow() << '\n';
    return 0;
}
